// Contenido del grado 7° (Estándares Básicos de Competencias en Lenguaje, MEN 2006; DBA de Lenguaje v2, MEN 2016)
import type { Grade } from './types';
const grade: Grade =
{id:'g7',n:7,title:'Tipos de texto, géneros y la oración',desc:'Para qué sirve cada texto, cómo se organizan los géneros literarios y cómo se arma una oración clara.',units:[
{id:'g7u1',title:'Textos con propósito',desc:'Tipologías textuales, texto expositivo y hechos frente a opiniones.',lessons:[
 {id:'g7u1l1',title:'Tipologías textuales',time:50,std:'Reconozco las características de los diversos tipos de texto que leo.',dba:'DBA 6 (7°): interpreta textos atendiendo al funcionamiento de la lengua, a las estrategias de lectura y al papel del interlocutor y del contexto.',
  body:['Todo texto se escribe para algo: esa es su <b>intención</b>. Según la intención y la manera de organizarse, los textos se agrupan en <b>tipologías textuales</b>. Hay cinco grandes: contar, describir, explicar, convencer y dar instrucciones.',
   'El texto <b>narrativo</b> cuenta hechos que pasan en el tiempo, como un cuento o una crónica. Usa verbos en pasado y marcas como <i>había una vez, aquella mañana, al final</i>.',
   'El texto <b>descriptivo</b> muestra cómo es algo o alguien, como un retrato o la ficha de un animal. Se llena de <b>adjetivos</b>: <i>bajita, blancas, ronca</i>.',
   'El texto <b>expositivo</b> explica un tema con datos claros y objetivos, como un artículo de enciclopedia. Casi siempre va en presente: <i>el frailejón atrapa el agua de la niebla</i>.',
   'El texto <b>argumentativo</b> defiende una opinión, llamada <b>tesis</b>, con razones, como una columna o un discurso. Lo delatan palabras como <i>creo, considero, debería, hay que</i> y conectores como <i>porque, ya que</i>.',
   'El texto <b>instructivo</b> indica paso a paso cómo hacer algo, como una receta o un manual. Usa verbos que dan órdenes: <i>pele, conecte, presente, mezcle</i>.',
   'Muchos textos reales <b>mezclan tipos</b>, pero siempre hay una <b>intención que domina</b>. Un aviso publicitario describe un celular y hasta cuenta una historia, pero lo que busca es convencerte de comprarlo.'],
  bites:[
   {ej:'Una receta de ajiaco, un cuento de la abuela y una columna del periódico se escriben para cosas distintas.',check:{q:'¿Qué es la intención de un texto?',o:['Para qué fue escrito','Cuántas páginas tiene','Quién lo imprimió'],a:0,e:'La intención es el propósito del texto: contar, describir, explicar, convencer o guiar.'}},
   {ej:'"Aquella mañana el bus se varó en la mitad del páramo."',ojo:'Pista: verbos en pasado y marcas de tiempo casi siempre indican un texto narrativo.'},
   {ej:'"Mi abuela es bajita, de manos arrugadas y voz suave, y siempre huele a café."',check:{q:'"La plaza tiene casas blancas con balcones de madera." ¿Qué tipo de texto es?',o:['Descriptivo','Narrativo','Instructivo'],a:0,e:'Muestra cómo es la plaza y usa adjetivos como "blancas".'}},
   {ej:'"La cumbia nació en la región Caribe de la mezcla de tradiciones indígenas, africanas y europeas."',ojo:'El expositivo explica, pero no opina: si ves "creo" o "debería", ya no es expositivo.'},
   {ej:'"Los colegios deberían tener huerta escolar, porque enseña a cuidar la tierra."',check:{q:'¿Qué palabra delata un texto argumentativo?',o:['Debería','Había una vez','Mezcle'],a:0,e:'"Debería" muestra una opinión que el autor quiere defender con razones.'}},
   {ej:'"Para votar, presente su cédula, firme la planilla y deposite el tarjetón en la urna."',ojo:'Truco: si el texto te da órdenes (pele, mezcle, conecte), es instructivo.',check:{q:'¿Qué tipo de texto es el manual de una licuadora?',o:['Instructivo','Narrativo','Descriptivo'],a:0,e:'Un manual indica paso a paso cómo usar algo.'}},
   {ej:'Un folleto de Cartagena describe las murallas, cuenta su historia y termina con "¡Ven a conocerla!": quiere convencerte de viajar.',ojo:'Pregúntate siempre: ¿para qué fue escrito? La respuesta es la intención que domina.',check:{q:'Un aviso de un celular lo describe y cuenta una historia. ¿Qué busca sobre todo?',o:['Convencerte de comprarlo','Explicar un tema','Darte instrucciones'],a:0,e:'La descripción y la historia están al servicio de convencer: esa es la intención que domina.'}}],
  key:'Narrar cuenta, describir muestra, exponer explica, argumentar convence e instruir guía paso a paso.',
  co:'En un mismo día puedes leer la receta del ajiaco santafereño (instructivo), un aviso de la alcaldía que explica el nuevo horario del pico y placa (expositivo) y una columna de opinión que lo critica (argumentativo).',
  act:{type:'classify',prompt:'Lee cada fragmento y toca su tipo de texto según su intención principal.',bins:['Narrativo','Descriptivo','Expositivo','Argumentativo','Instructivo'],items:[
   ['Pele las papas, córtelas en rodajas y échelas a la olla con el pollo y las guascas.',4],
   ['Había una vez un pescador de Honda que nunca volvía con la canoa vacía.',0],
   ['El frailejón es una planta del páramo que atrapa el agua de la niebla y la suelta poco a poco.',2],
   ['Considero que el pico y placa no resuelve el trancón: la ciudad necesita más metro y menos carros.',3],
   ['La plaza tiene casas blancas con balcones de madera y, en el centro, una fuente de piedra.',1],
   ['Para votar, presente su cédula, firme la planilla y deposite el tarjetón en la urna.',4],
   ['El sábado llegamos a Mompox, dejamos las maletas y salimos a caminar por la orilla del río.',0],
   ['Los colegios deberían tener huerta escolar, porque enseña a cuidar la tierra y mejora la alimentación.',3],
   ['Mi abuela es bajita, de manos arrugadas y voz suave, y siempre huele a café.',1],
   ['La cumbia nació en la región Caribe de la mezcla de tradiciones indígenas, africanas y europeas.',2]],
   e:'Pregúntate para qué fue escrito cada texto: ¿contar, mostrar, explicar, convencer o guiar?'},
  quiz:[{q:'¿Cuál es la intención principal de un texto instructivo?',o:['Contar una historia','Indicar paso a paso cómo hacer algo','Defender una opinión','Describir un paisaje'],a:1,e:'Recetas, manuales e instrucciones guían al lector para que realice una tarea.',lv:'L'},
   {q:'Una columna dice: "El reciclaje en los colegios debería ser obligatorio, porque reduce la basura y crea buenos hábitos". ¿Qué tipo de texto es?',o:['Narrativo','Descriptivo','Argumentativo','Instructivo'],a:2,e:'Presenta una opinión ("debería ser obligatorio") y la sostiene con razones introducidas por "porque".',lv:'I'},
   {q:'Un folleto turístico de Cartagena describe las murallas, cuenta su historia y termina con "¡Ven a conocerla!". ¿Qué se puede afirmar?',o:['Que es solo descriptivo','Que es narrativo porque cuenta una historia','Que no tiene ninguna intención','Que mezcla tipologías, pero su intención dominante es convencer al lector de viajar'],a:3,e:'Descripción y narración están al servicio de una intención: persuadir al turista.',lv:'C'}],
  tip:'Lleve una receta, un recibo de servicios, una columna, un cuento y la ficha de un animal; los grupos deben adivinar la intención leyendo solo la primera línea.'},
 {id:'g7u1l2',title:'El texto expositivo y la idea principal',time:50,std:'Comprendo e interpreto diversos tipos de texto, para establecer sus relaciones internas y su clasificación en una tipología textual.',dba:'DBA 6 (7°): interpreta textos atendiendo al funcionamiento de la lengua, a las estrategias de lectura y al papel del interlocutor y del contexto.',
  body:['El <b>texto expositivo</b> explica un tema de forma clara y <b>objetiva</b>. Usa datos, definiciones y ejemplos, y no da la opinión del autor.',
   'Se organiza en tres partes. La <b>introducción</b> presenta el tema. El <b>desarrollo</b> lo explica por partes, con marcas como <i>primero, además</i>. El <b>cierre</b> resume o concluye, a menudo con <i>por eso</i> o <i>en conclusión</i>.',
   'Como busca ser objetivo, sus datos deben poder <b>comprobarse</b>. Por eso cita <b>fuentes confiables</b>: una entidad oficial, un instituto de investigación o una enciclopedia.',
   'Cada párrafo gira alrededor de una <b>idea principal</b>: lo más importante que dice. Las <b>ideas secundarias</b> la amplían con ejemplos, datos o detalles.',
   'Haz la prueba de borrar. Si quitas una idea secundaria, el párrafo conserva su sentido. Si quitas la idea principal, el párrafo se queda sin centro.',
   'Para encontrarla, pregúntate <b>de qué habla</b> el párrafo (el <b>tema</b>) y <b>qué dice</b> sobre eso. Muchas veces está en la primera oración, la <b>oración temática</b>. A veces aparece al final, como conclusión de los detalles.',
   'Si unes las ideas principales de todos los párrafos, obtienes un <b>resumen</b> o un <b>mapa conceptual</b> del texto. Los detalles quedan por fuera.'],
  bites:[
   {ej:'Un artículo de enciclopedia sobre el páramo de Sumapaz explica qué es, dónde está y por qué es importante.',check:{q:'¿Qué hace un texto expositivo?',o:['Explica un tema con datos','Cuenta una aventura','Da la opinión del autor'],a:0,e:'El expositivo explica de forma clara y objetiva.'}},
   {ej:'Introducción: "Sumapaz es el páramo más grande del mundo". Cierre: "Por eso, cuidarlo es cuidar el agua".',ojo:'"Primero" y "además" suelen estar en el desarrollo; "por eso" y "en conclusión", en el cierre.',check:{q:'¿Qué parte presenta el tema?',o:['La introducción','El desarrollo','El cierre'],a:0,e:'La introducción anuncia de qué se va a hablar.'}},
   {ej:'Un texto sobre Sumapaz puede citar a Parques Nacionales Naturales o al Instituto Humboldt.',ojo:'Un blog anónimo no es una fuente confiable: no se sabe quién comprobó los datos.'},
   {ej:'Idea principal: "Los páramos son fábricas de agua". Secundaria: "Sus plantas atrapan la humedad de la niebla".',check:{q:'¿Qué hacen las ideas secundarias?',o:['Amplían la idea principal con detalles','Cambian de tema','Cierran el texto'],a:0,e:'Son ejemplos, datos o detalles que apoyan la idea principal.'}},
   {ej:'Borra "De allí nace el río Tunjuelo" y el párrafo sigue hablando del agua del páramo. Borra "Sumapaz es una esponja de agua" y ya no se entiende.',ojo:'Truco: la idea principal es la que no puedes borrar.'},
   {ej:'"Los frailejones crecen un centímetro al año. Uno de dos metros puede tener dos siglos. Cortarlo es perder en minutos lo que tardó siglos." La idea principal va al final.',check:{q:'¿Dónde está siempre la idea principal?',o:['No siempre en el mismo lugar: suele ir al inicio, pero puede ir al final','Siempre en la última palabra','En el título'],a:0,e:'Muchas veces está en la oración temática del inicio, pero puede ir al final.'}},
   {ej:'Cinco párrafos sobre Sumapaz dan cinco ideas: qué es, su función, su vida, su problema y la conclusión.',check:{q:'Si unes las ideas principales de un texto, obtienes…',o:['Un resumen','Un cuento','Una lista de detalles'],a:0,e:'Las ideas principales juntas forman el resumen o el mapa conceptual.'}}],
  key:'Tema: de qué habla. Idea principal: qué dice sobre eso. Las secundarias la explican con ejemplos y datos.',
  co:'El páramo de Sumapaz, que ocupa buena parte de la localidad 20 de Bogotá, es considerado el más grande del mundo y regula el agua que llega a la ciudad y a la región.',
  act:{type:'map',kind:'concept',center:'Páramo de Sumapaz',prompt:'Lee el texto y lleva la idea principal de cada párrafo a su casilla. Sobran tarjetas con detalles.<br><br>(1) El páramo de Sumapaz, al sur de Bogotá, es el páramo más grande del mundo. Ocupa parte de Bogotá, Cundinamarca, Meta y Huila.<br>(2) Sus frailejones y musgos funcionan como esponjas: atrapan el agua de la niebla y la sueltan despacio. De allí nacen ríos como el Tunjuelo y el Sumapaz.<br>(3) En Sumapaz viven el oso de anteojos, el venado y muchas plantas que solo crecen en los páramos.<br>(4) La ganadería, los cultivos de papa y las quemas amenazan el páramo, porque secan el suelo y destruyen la vegetación.<br>(5) Por eso, cuidar Sumapaz es cuidar el agua de millones de personas.',
   slots:[{label:'Párrafo 1 · Qué es',a:'El páramo más grande del mundo'},{label:'Párrafo 2 · Función',a:'Una esponja que regula el agua'},{label:'Párrafo 3 · Vida',a:'Hogar de especies únicas'},{label:'Párrafo 4 · Problema',a:'Lo amenazan la ganadería, los cultivos y las quemas'},{label:'Párrafo 5 · Conclusión',a:'Cuidarlo es cuidar el agua'}],
   extra:['Ocupa parte del Huila','De allí nace el río Tunjuelo','Allí vive el venado'],
   e:'Las tarjetas que sobran son ideas secundarias: detalles que apoyan la idea principal de su párrafo.'},
  quiz:[{q:'En un texto expositivo, ¿qué hace la introducción?',o:['Presenta el tema','Da la opinión del autor','Cuenta una historia','Da instrucciones'],a:0,e:'La introducción anuncia de qué se va a hablar; el desarrollo lo explica y el cierre concluye.',lv:'L'},
   {q:'"Los frailejones crecen muy despacio: más o menos un centímetro al año. Un frailejón de dos metros puede tener cerca de dos siglos. Cortarlo es perder en minutos lo que el páramo tardó siglos en formar." ¿Cuál es la idea principal?',o:['Los frailejones miden dos metros','Los frailejones crecen tan despacio que destruirlos es una pérdida enorme','Un frailejón crece un centímetro','Los páramos son fríos'],a:1,e:'Las cifras son ideas secundarias: sirven para demostrar la idea central sobre el crecimiento lento y la pérdida.',lv:'I'},
   {q:'¿Por qué un texto expositivo sobre Sumapaz debería citar fuentes como Parques Nacionales Naturales o el Instituto Humboldt?',o:['Para que sea más largo','Porque los datos de un texto expositivo deben poder comprobarse','Porque es obligatorio poner nombres propios','Para que parezca un cuento'],a:1,e:'El texto expositivo busca ser objetivo; citar fuentes confiables permite verificar lo que afirma.',lv:'C'}],
  tip:'Entregue un texto expositivo con los párrafos recortados; cada grupo escribe la idea principal de cada uno en un papelito y arma el mapa conceptual en el tablero.'},
 {id:'g7u1l3',title:'Hechos y opiniones en los medios',time:50,std:'Selecciono y clasifico la información emitida por los medios de comunicación masiva.',dba:'DBA 1 (7°): clasifica la información que circula en los medios de comunicación y la retoma como referente para sus producciones.',
  body:['En los medios circulan <b>hechos</b> y <b>opiniones</b>. Un <b>hecho</b> es algo que ocurrió y se puede <b>comprobar</b>: un marcador, una fecha, una cifra, una declaración grabada.',
   'Una <b>opinión</b> es lo que alguien piensa o siente sobre un hecho. La delatan los <b>adjetivos valorativos</b> (<i>mejor, vergonzoso, histórico, emocionante, horrible</i>), verbos como <i>creo, considero, debería</i> y expresiones como <i>sin duda</i> o <i>para mí</i>.',
   'Las <b>predicciones</b> tampoco son hechos. "Ganaremos el Mundial" todavía no se puede comprobar: es un deseo sobre el futuro.',
   'Las opiniones no son malas: la columna y el editorial existen para darlas. El problema es presentar una opinión <b>como si fuera un hecho</b>. Un lector crítico separa lo que pasó de lo que alguien piensa, y busca la <b>fuente</b>.',
   'Ante una noticia, pregúntate si es confiable, engañosa o falsa. Es <b>confiable</b> si tiene una fuente reconocida, fecha y datos precisos, y otros medios la confirman.',
   'Es <b>engañosa</b> si parte de un hecho real, pero lo saca de su fecha (una foto vieja que circula como nueva) o lo presenta con una valoración exagerada ("fracaso total").',
   'Es <b>falsa</b> si es inventada. Viene de cuentas anónimas o cadenas sin fecha, no cita documentos, ningún medio serio la confirma o promete algo imposible.'],
  bites:[
   {ej:'"La Selección Colombia le ganó 2-1 a Ecuador en Barranquilla": el marcador y el lugar se pueden verificar.',check:{q:'¿Cuál es un hecho?',o:['El partido terminó 2-1','Fue un partido aburridísimo','El técnico debería renunciar'],a:0,e:'El marcador se puede comprobar; las otras frases son valoraciones.'}},
   {ej:'"Fue el partido más emocionante de la década." "El técnico debería darles más minutos a los jóvenes."',ojo:'Busca las palabras que juzgan: mejor, peor, vergonzoso, debería, sin duda.',check:{q:'En "Vergonzosa derrota de la Selección", ¿qué palabra opina?',o:['Vergonzosa','Derrota','Selección'],a:0,e:'"Vergonzosa" es un adjetivo valorativo: juzga el hecho.'}},
   {ej:'"Sin duda, el próximo año ganaremos la Copa" es una predicción: nadie puede comprobarla hoy.',check:{q:'"Mañana lloverá en Bogotá." ¿Se puede comprobar hoy?',o:['No, es una predicción','Sí, es un hecho'],a:0,e:'Habla del futuro: todavía no ha pasado, así que no es un hecho.'}},
   {ej:'Un noticiero dice "Colombia jugó su peor partido en años" como si fuera un dato, sin cifras ni fuentes.',ojo:'No se trata de desconfiar de todo, sino de separar el dato de la valoración.'},
   {ej:'"Colombia, subcampeona de la Copa América 2024 tras caer 1-0 ante Argentina", publicado el 15 de julio de 2024 por varios medios.',check:{q:'¿Qué hace confiable una noticia?',o:['Fuente reconocida, fecha, datos precisos y otros medios que la confirman','Que la compartan muchos amigos','Que tenga un titular emocionante'],a:0,e:'Una noticia confiable se puede verificar en varias fuentes.'}},
   {ej:'Una foto de Colombia campeona en 2001 circula hoy con el titular "¡Colombia, campeona de América!".',ojo:'Engañosa no es lo mismo que falsa: el hecho existió, pero está sacado de su fecha o exagerado.'},
   {ej:'"Científicos confirman: ver jugar a la Selección cura la gripa", en un blog sin fecha ni nombres.',check:{q:'Una cuenta anónima dice que un jugador vuelve por 500 millones de euros y nadie lo confirma. ¿Qué es?',o:['Falsa','Confiable','Engañosa'],a:0,e:'No tiene fuente, nadie la confirma y la cifra es imposible: es inventada.'}}],
  key:'Hecho: se puede comprobar. Opinión: es una valoración. Un buen lector no los confunde.',
  co:'En la Copa América 2024 Colombia llegó a la final después de 28 partidos sin perder: eso es un hecho. Decir que fue "la mejor Selección de la historia" ya es una opinión.',
  act:{type:'mark',prompt:'Elige un color y toca en la nota los hechos (verde) y las opiniones (naranja).',cats:[{n:'Hecho',c:'#2F7D32'},{n:'Opinión',c:'#D9822B'}],text:'[[La Selección Colombia le ganó 2-1 a Ecuador en el estadio Metropolitano de Barranquilla|0]]. [[Fue el partido más emocionante de la década|1]]. [[Los dos goles colombianos llegaron en el segundo tiempo|0]] y [[más de 40.000 personas llenaron las tribunas|0]]. [[El técnico debería darles más minutos a los jugadores jóvenes|1]], porque [[el equipo se ve cansado|1]]. [[Con este resultado, Colombia suma 10 puntos en la tabla|0]]. [[Sin duda, es la mejor Selección de la historia|1]].',e:'Los hechos tienen cifras, lugares y resultados que se pueden verificar; las opiniones usan "debería", "sin duda", "más emocionante" o "la mejor".'},
  quiz:[{q:'¿Cuál de estas frases es un hecho?',o:['James es el jugador más elegante del mundo','Colombia fue campeona de la Copa América en 2001','El fútbol colombiano es el más alegre del continente','La Selección debería jugar siempre en Barranquilla'],a:1,e:'Colombia ganó la Copa América de 2001, que se jugó en el país: es un dato comprobable.',lv:'L'},
   {q:'Un titular dice: "Vergonzosa derrota de la Selección". ¿Qué palabra muestra que hay una opinión?',o:['Derrota','Selección','Vergonzosa','de la'],a:2,e:'"Vergonzosa" es un adjetivo valorativo: juzga el hecho en lugar de solo informarlo.',lv:'I'},
   {q:'Un noticiero presenta "Colombia jugó su peor partido en años" como si fuera un dato, sin cifras ni fuentes. ¿Qué debe hacer un lector crítico?',o:['Reconocer que es una valoración y buscar datos (remates, posesión, resultados) para contrastarla','Aceptarlo porque lo dijo la televisión','Dejar de ver fútbol','Pensar que todo lo que dicen los medios es falso'],a:0,e:'No se trata de desconfiar de todo, sino de distinguir la valoración y contrastarla con datos verificables.',lv:'C'}],
  tip:'Proyecte tres titulares del mismo partido publicados por medios distintos; los estudiantes subrayan las palabras que opinan y comparan cuál informa mejor.'}
]},
{id:'g7u2',title:'Géneros literarios',desc:'Narrativo, lírico y dramático; el narrador; literatura y época.',lessons:[
 {id:'g7u2l1',title:'Narrativo, lírico y dramático',time:50,std:'Comparo los procedimientos narrativos, líricos o dramáticos empleados en la literatura que permiten estudiarla por géneros.',dba:'DBA 4 (7°): comprende que el género lírico es una construcción mediada por la musicalidad, la rima y las figuras retóricas, que recrean una idea, un sentimiento o una situación.',
  body:['Las obras literarias se agrupan en tres grandes <b>géneros</b>. El primero es el <b>narrativo</b>: cuenta una historia con personajes, espacio y tiempo. Quien la cuenta es un <b>narrador</b>.',
   'Subgéneros narrativos: el <b>cuento</b> (relato breve), la <b>novela</b> (relato largo, como <i>María</i>, de Jorge Isaacs), la <b>fábula</b> (relato breve con animales y moraleja), el <b>mito</b> y la <b>leyenda</b>.',
   'El <b>lírico</b> expresa sentimientos, emociones o una mirada íntima del mundo. Casi siempre va en verso, con ritmo, rima e imágenes. Habla el <b>yo lírico</b>. José Asunción Silva, en su "Nocturno", convierte en música el recuerdo de una noche.',
   'Subgéneros líricos: la <b>oda</b> (celebra algo o a alguien), la <b>elegía</b> (lamenta una pérdida), el <b>soneto</b> (poema de catorce versos) y la <b>copla</b> (estrofa popular breve, hecha para cantar).',
   'El <b>dramático</b> se escribe para ser <b>representado</b>. No hay narrador: los personajes hablan en <b>diálogos</b>, y cada parlamento va después del nombre del personaje. Las <b>acotaciones</b>, entre paréntesis, indican gestos, movimientos y escenario.',
   'Subgéneros dramáticos: la <b>tragedia</b> (conflicto serio y final desdichado), la <b>comedia</b> (tono alegre y final feliz) y el <b>drama</b> (mezcla lo serio y lo cotidiano). El Festival Iberoamericano de Teatro de Bogotá lleva estas obras a escena.',
   'Para saber el género, fíjate en <b>quién habla</b>: alguien cuenta (narrativo), un yo expresa lo que siente (lírico) o los personajes dialogan en escena (dramático). Ojo: el <b>verso es una forma, no un género</b>.'],
  bites:[
   {ej:'"Había una vez un pueblo junto al río donde nunca dejaba de llover": alguien nos cuenta una historia.',check:{q:'¿Qué hace el género narrativo?',o:['Cuenta una historia','Expresa lo que siente un yo','Se escribe solo para actuar'],a:0,e:'El narrativo cuenta, a través de un narrador, una historia con personajes.'}},
   {ej:'"El zorro miró las uvas, saltó tres veces y se fue diciendo que estaban verdes": fábula, con animales y moraleja.',ojo:'Cuento y fábula son breves; la fábula, además, tiene animales y deja una enseñanza.'},
   {ej:'"Una noche, / una noche toda llena de perfumes, de murmullos y de música de alas…" (José Asunción Silva).',check:{q:'¿Quién habla en un poema lírico?',o:['El yo lírico','Un narrador que cuenta','Varios personajes en diálogo'],a:0,e:'En la lírica un yo expresa sus emociones.'}},
   {ej:'Una copla del Caribe se canta en las fiestas; una elegía se escribe cuando muere alguien querido.',ojo:'Truco: la oda celebra y la elegía lamenta.',check:{q:'¿Cuántos versos tiene un soneto?',o:['Catorce','Cuatro','Cien'],a:0,e:'El soneto es un poema de catorce versos.'}},
   {ej:'"JUANA. — (Asomándose a la ventana) ¡Ya llegó el circo!" Lo que va entre paréntesis es una acotación.',check:{q:'¿Qué indican las acotaciones?',o:['Gestos, movimientos y escenario','La moraleja','El nombre del autor'],a:0,e:'Van entre paréntesis y guían a los actores.'}},
   {ej:'Una comedia en el Festival de Teatro hace reír y termina bien; una tragedia termina en desgracia.',check:{q:'Una obra de teatro con final feliz y tono alegre es una…',o:['Comedia','Tragedia','Elegía'],a:0,e:'La comedia tiene tono alegre y final feliz.'}},
   {ej:'"El renacuajo paseador", de Rafael Pombo, está en verso, pero cuenta una historia con personajes y final: es narrativo.',ojo:'No te dejes engañar por los versos: una fábula en verso sigue siendo narrativa.',check:{q:'"LUCÍA. — (Con rabia) ¡No pienso volver!" ¿Qué género es?',o:['Dramático','Lírico','Narrativo'],a:0,e:'Hay nombre de personaje, diálogo y acotación: es teatro.'}}],
  key:'Narrativo: alguien cuenta. Lírico: alguien expresa lo que siente. Dramático: los personajes hablan y actúan en escena.',
  co:'Rafael Pombo contó historias en verso ("El renacuajo paseador"), Silva escribió poesía lírica y, desde 1988, el Festival Iberoamericano de Teatro llena Bogotá de obras dramáticas.',
  act:{type:'match',prompt:'Une cada subgénero con lo que lo define.',pairs:[
   ['Novela','Relato largo, como María'],
   ['Fábula','Relato breve con animales y moraleja'],
   ['Oda','Poema que celebra algo o a alguien'],
   ['Elegía','Poema que lamenta una pérdida'],
   ['Soneto','Poema de catorce versos'],
   ['Copla','Estrofa popular breve para cantar'],
   ['Tragedia','Teatro con final desdichado'],
   ['Comedia','Teatro alegre con final feliz']],
   e:'Novela y fábula son narrativas; oda, elegía, soneto y copla son líricas; tragedia y comedia son dramáticas.'},
  quiz:[{q:'¿Qué género literario se escribe para ser representado en un escenario?',o:['Narrativo','Lírico','Dramático','Expositivo'],a:2,e:'El texto dramático está hecho para que actores lo representen ante un público.',lv:'L'},
   {q:'Un texto dice: "LUCÍA. — (Con rabia) ¡No pienso volver! / MARTÍN. — Entonces vete". ¿Cómo sabes a qué género pertenece?',o:['Porque rima','Porque tiene diálogos con nombres de personajes y acotaciones entre paréntesis','Porque tiene un narrador','Porque explica un tema'],a:1,e:'Diálogos encabezados por el nombre del personaje y acotaciones son marcas del género dramático.',lv:'I'},
   {q:'"El renacuajo paseador", de Pombo, está escrito en verso, pero cuenta una historia con personajes, un conflicto y un final. ¿Qué género domina?',o:['Lírico, porque tiene versos','Dramático, porque hay personajes','Ninguno de los tres','Narrativo, porque lo central es la historia que se cuenta'],a:3,e:'El verso es una forma, no un género: una fábula en verso sigue siendo narrativa.',lv:'C'}],
  tip:'Lean el mismo tema (la lluvia) en un cuento breve, un poema y una escena de dos personajes; los grupos explican qué cambió de un género a otro.'},
 {id:'g7u2l2',title:'El narrador y el punto de vista',time:50,std:'Reconozco en las obras literarias procedimientos narrativos, líricos o dramáticos.',dba:'DBA 3 (7°): clasifica las producciones literarias a partir del análisis de su contenido y su estructura.',
  body:['Todo relato tiene un <b>narrador</b>: la voz que cuenta la historia. El narrador <b>no es el autor</b>. García Márquez escribió <i>Cien años de soledad</i>, pero quien narra es una voz que él inventó.',
   'El narrador decide <b>desde dónde</b> se mira la historia: eso es el <b>punto de vista</b>. Hay tres narradores principales: protagonista, testigo y omnisciente.',
   'El narrador <b>protagonista</b> cuenta en <b>primera persona</b> (<i>yo, nosotros</i>) lo que le pasó a él: "yo sentí…". Solo sabe lo que ve y piensa.',
   'El narrador <b>testigo</b> también puede hablar en primera persona ("yo vi…", "las vecinas oímos…"), pero cuenta lo que le pasó a <b>otro</b>. Solo conoce lo que presenció o lo que otros le contaron, no lo que el otro piensa.',
   'El narrador <b>omnisciente</b> cuenta en <b>tercera persona</b> (<i>él, ella, ellos</i>: "ella remó…") y lo sabe todo: lo que piensan y sienten todos los personajes, lo que pasó antes y lo que pasará.',
   'Para narrar casi siempre se usa la primera o la tercera persona. La <b>segunda persona</b> (<i>tú</i>: "tú remas hasta la orilla") casi no se usa.',
   'Cambiar de narrador cambia lo que sabemos y lo que sentimos. La leyenda del Mohán no es igual contada por el pescador, por un vecino o por una voz omnisciente.'],
  bites:[
   {ej:'Rafael Pombo escribió "El renacuajo paseador", pero la voz que cuenta la historia es un narrador que él creó.',check:{q:'¿Quién es el narrador?',o:['La voz que cuenta la historia','La persona real que escribe el libro'],a:0,e:'El autor es la persona real; el narrador es una voz inventada.'}},
   {ej:'Una misma pelea en el recreo se ve distinta desde quien la vivió, desde quien la vio o desde una cámara que lo graba todo.',check:{q:'¿Qué es el punto de vista?',o:['Desde dónde se mira la historia','El final de la historia','El título del cuento'],a:0,e:'El punto de vista es el lugar desde el que el narrador mira y cuenta.'}},
   {ej:'"Yo tiraba la atarraya cuando sentí que alguien me miraba desde el agua."',ojo:'Pista: "yo" más "me pasó a mí" = protagonista.'},
   {ej:'"Desde la ventana vi a don Efraín salir con la atarraya; nunca supe por qué no volvió."',ojo:'El testigo dice "yo", pero la historia es de otro. No sabe lo que el otro piensa.',check:{q:'"Vi a mi vecino salir con la atarraya y no regresar." ¿Qué narrador es?',o:['Testigo','Protagonista','Omnisciente'],a:0,e:'Cuenta lo que presenció que le pasó a otro.'}},
   {ej:'"El Mohán sabía que el pescador tenía miedo, y el pescador, sin saberlo, pensaba en su hija."',check:{q:'¿Qué narrador conoce los pensamientos de todos?',o:['Omnisciente','Testigo','Protagonista'],a:0,e:'"Omnisciente" significa que lo sabe todo.'}},
   {ej:'Primera: "yo remé". Segunda: "tú remas". Tercera: "ella remó".',ojo:'Fíjate en los pronombres y en el verbo para saber la persona.',check:{q:'"Ella remó hasta la orilla." ¿En qué persona está?',o:['Tercera','Primera','Segunda'],a:0,e:'"Ella" es tercera persona.'}},
   {ej:'Si el Mohán narra su propia leyenda, conocemos sus razones y podemos verlo menos como monstruo y más como personaje.',check:{q:'¿Cambiar de narrador cambia la historia que leemos?',o:['Sí, cambia lo que sabemos y sentimos','No, todo queda igual'],a:0,e:'Cada narrador sabe cosas distintas y nos acerca a personajes distintos.'}}],
  key:'Protagonista: "me pasó a mí". Testigo: "vi lo que le pasó a otro". Omnisciente: lo sabe todo, en tercera persona.',
  co:'El Mohán, dueño de los ríos del Tolima y el Huila, aparece en historias de pescadores y lavanderas del Magdalena; cada narrador lo ve de una manera distinta.',
  act:{type:'choose',prompt:'La misma leyenda del Mohán contada por voces distintas. Toca qué narrador habla.',items:[
   {s:'"Yo tiraba la atarraya cuando sentí que alguien me miraba desde el agua."',o:['Protagonista','Testigo','Omnisciente'],a:0,e:'Cuenta en primera persona lo que le pasó a él: "yo sentí".'},
   {s:'"Vi al pescador remar asustado hacia la orilla; desde mi ventana no alcancé a ver qué lo perseguía."',o:['Protagonista','Testigo','Omnisciente'],a:1,e:'Dice "vi", pero cuenta lo que le pasó a otro y no lo sabe todo.'},
   {s:'"El Mohán sabía que el pescador tenía miedo, y el pescador, sin saberlo, pensaba en su hija."',o:['Protagonista','Testigo','Omnisciente'],a:2,e:'Conoce lo que piensan los dos personajes: lo sabe todo.'},
   {s:'"Soy el dueño del río: desde mi cueva bajo las piedras escucho a cada lavandera que canta."',o:['Protagonista','Testigo','Omnisciente'],a:0,e:'El Mohán cuenta su propia historia en primera persona.'},
   {s:'"Mi compadre nos contó en la tienda que esa noche el río estaba raro; nosotros solo oímos a los perros."',o:['Protagonista','Testigo','Omnisciente'],a:1,e:'Cuenta lo que otros le contaron; la historia no es suya.'},
   {s:'"Todos en Honda dormían, pero el río guardaba un secreto que ni el pescador imaginaba."',o:['Protagonista','Testigo','Omnisciente'],a:2,e:'Está en tercera persona y sabe lo que ni el personaje sabe.'},
   {s:'García Márquez escribió Cien años de soledad. ¿Quién cuenta la historia dentro del libro?',o:['García Márquez en persona','Una voz narradora que él inventó'],a:1,e:'El autor es la persona real; el narrador es una voz creada por él.'}],
   e:'Pregúntate de quién es la historia y cuánto sabe la voz que la cuenta.'},
  quiz:[{q:'¿Qué narrador conoce los pensamientos de todos los personajes?',o:['Protagonista','Testigo','Omnisciente','El autor'],a:2,e:'"Omnisciente" significa que lo sabe todo.',lv:'L'},
   {q:'"Desde la ventana vi a don Efraín salir con la atarraya; nunca supe por qué no volvió." ¿Qué tipo de narrador es?',o:['Protagonista','Testigo','Omnisciente'],a:1,e:'Habla en primera persona, pero cuenta lo que le pasó a otro y no sabe todo: es testigo.',lv:'I'},
   {q:'Si la leyenda del Mohán la narra el propio Mohán, ¿qué cambia?',o:['Nada, la historia es igual','Se vuelve un texto instructivo','Conocemos sus razones y podemos verlo menos como un monstruo y más como un personaje','El relato pierde el conflicto'],a:2,e:'Cambiar el punto de vista cambia la información y la simpatía del lector hacia los personajes.',lv:'C'}],
  tip:'Pida reescribir un párrafo de la leyenda cambiando de narrador (de omnisciente al pescador en primera persona) y contarlo en voz alta; comparen qué se pierde y qué se gana.'},
 {id:'g7u2l3',title:'La literatura cuenta su época',time:50,std:'Formulo hipótesis de comprensión acerca de las obras literarias que leo teniendo en cuenta género, temática, época y región.',dba:'DBA 3 (7°): clasifica las producciones literarias a partir del análisis de su contenido y su estructura.',
  body:['Ninguna obra nace en el vacío. Toda obra responde a su <b>contexto</b>: el momento histórico, la sociedad, las costumbres y las ideas de su época. Conocerlo ayuda a entender por qué una obra dice lo que dice.',
   'Rafael <b>Pombo</b> nació en Bogotá en 1833 y murió allí en 1912: casi toda su obra es del <b>siglo XIX</b>. Su Bogotá era pequeña, de calles empedradas, iglesias y chicherías. El país vivía guerras civiles entre liberales y conservadores.',
   'En 1855 Pombo viajó a <b>Nueva York</b> como diplomático. Allí publicó sus <b>Cuentos pintados para niños</b> (1867) y sus <b>Cuentos morales para niños formales</b> (1869). En esa época se pensaba que la literatura infantil debía <b>enseñar buenas costumbres</b>.',
   'Por eso sus fábulas dejan una <b>moraleja</b>: obedecer a los padres, no ser vanidoso, ser prudente. Rinrín Renacuajo desobedece a su madre y termina tragado por un pato. Hoy podemos disfrutarlas y <b>preguntarnos</b> qué valores siguen vigentes y cuáles cambiaron.',
   'Arma su <b>línea de tiempo</b>. 1810: Grito de Independencia en Santafé, hoy Bogotá. 1867: Jorge Isaacs publica la novela <b>María</b>. 1884: empieza a rodar el tranvía de mulas. 1892: abre el Teatro Colón. 1899-1902: <b>Guerra de los Mil Días</b>. 1905: Pombo, <b>poeta nacional</b>.',
   'La literatura también se agrupa en <b>movimientos</b>. El <b>Romanticismo</b> (mediados del siglo XIX) exaltó la emoción y la naturaleza, como <i>María</i> (1867). El <b>Modernismo</b> (fines del XIX) buscó la música del verso, como el "Nocturno" de José Asunción Silva (1894).',
   'En el siglo XX llegaron <i>La vorágine</i> de José Eustasio Rivera (1924), novela de la selva y las caucherías; las <b>vanguardias</b> (años 20 y 30), con formas nuevas, y el <b>boom latinoamericano</b> (años 60 y 70), con <i>Cien años de soledad</i> (1967).'],
  bites:[
   {ej:'Una canción de hoy habla de celulares y redes; una de hace cien años no podía hacerlo. Su época se nota.',check:{q:'¿Qué es el contexto de una obra?',o:['La época, la sociedad y las ideas que la rodean','El número de páginas','El color de la portada'],a:0,e:'El contexto es el mundo en el que nació la obra.'}},
   {ej:'Cuando Pombo era niño, Bogotá no tenía luz eléctrica y se tomaba chicha en las chicherías.',ojo:'Siglo XIX = años 1801 a 1900. Pombo vivió de 1833 a 1912.',check:{q:'¿En qué siglo escribió Pombo la mayor parte de su obra?',o:['Siglo XIX','Siglo XXI','Siglo XVII'],a:0,e:'Nació en 1833: casi toda su obra es del siglo XIX.'}},
   {ej:'"El renacuajo paseador" es parte de los Cuentos pintados para niños, publicados en Nueva York.',check:{q:'¿Para qué se pensaba en el siglo XIX que servía la literatura infantil?',o:['Para enseñar buenas costumbres','Para vender juguetes','Para hablar de tecnología'],a:0,e:'Por eso los cuentos de Pombo buscan enseñar conductas.'}},
   {ej:'Rinrín sale de paseo sin permiso de su madre y termina tragado por un pato: la moraleja es obedecer.',ojo:'Leer críticamente no es rechazar lo antiguo ni aceptarlo todo: es comparar su época con la nuestra.'},
   {ej:'Para medir la distancia con Pombo: la televisión llegó a Colombia en 1954 y TransMilenio, en 2000.',ojo:'La tele (1954) y TransMilenio (2000) llegaron mucho después de Pombo: no caben en su línea de tiempo.',check:{q:'¿Qué llegó primero a Bogotá?',o:['El tranvía de mulas','TransMilenio'],a:0,e:'El tranvía empezó en 1884; TransMilenio, en 2000.'}},
   {ej:'En María, de Jorge Isaacs, el paisaje del Valle del Cauca y el amor triste llenan cada página: puro Romanticismo.',check:{q:'¿Qué movimiento buscó la música del verso?',o:['Modernismo','Romanticismo'],a:0,e:'El Modernismo, como el "Nocturno" de Silva, cuidó el ritmo y la música.'}},
   {ej:'Cien años de soledad, de García Márquez, se publicó en 1967, un siglo después de María.',ojo:'Orden de los movimientos: Romanticismo, Modernismo, vanguardias y boom.',check:{q:'¿A qué movimiento pertenece Cien años de soledad?',o:['Boom latinoamericano','Romanticismo','Modernismo'],a:0,e:'Es la novela más famosa del boom, de los años 60 y 70.'}}],
  key:'Obra + contexto: la época explica los temas, los valores y la forma de una obra.',
  co:'Cuando Pombo publicó sus cuentos pintados, Bogotá no tenía luz eléctrica: el tranvía de mulas llegó en 1884 y el Teatro Colón abrió en 1892.',
  act:{type:'order',prompt:'Ordena la Bogotá de Pombo del hecho más antiguo al más reciente.',items:[
   'Grito de Independencia en Santafé',
   'Nace Rafael Pombo en Bogotá',
   'Pombo viaja a Nueva York como diplomático',
   'Jorge Isaacs publica María',
   'Empieza a rodar el tranvía de mulas',
   'Guerra de los Mil Días',
   'Pombo es coronado poeta nacional'],
   e:'1810, 1833, 1855, 1867, 1884, 1899-1902 y 1905: Pombo vivió la Bogotá que pasó de las guerras civiles al tranvía.'},
  quiz:[{q:'¿En qué siglo escribió Rafael Pombo la mayor parte de su obra?',o:['Siglo XVII','Siglo XVIII','Siglo XIX','Siglo XXI'],a:2,e:'Nació en 1833 y murió en 1912; casi toda su obra es del siglo XIX.',lv:'L'},
   {q:'Muchas fábulas de Pombo terminan con una moraleja. ¿Qué nos dice eso de su época?',o:['Que se pensaba que la literatura para niños debía enseñar conductas','Que los niños no sabían leer','Que no había animales en Bogotá','Que la gente solo leía teatro'],a:0,e:'La moraleja refleja la idea del siglo XIX de que leer debía formar buenas costumbres.',lv:'I'},
   {q:'Rinrín Renacuajo es castigado por desobedecer a su madre. ¿Cuál es una lectura crítica de la fábula hoy?',o:['Prohibirla porque es antigua','Disfrutarla y preguntarse qué valores siguen vigentes y cuáles han cambiado','Creer que todo lo antiguo es verdad','Ignorar la moraleja'],a:1,e:'Leer críticamente es relacionar la obra con su época y con la nuestra, sin rechazarla ni aceptarla sin pensar.',lv:'C'}],
  tip:'Cada grupo investiga un elemento de la Bogotá de fines del siglo XIX (el tranvía, la chichería, el farol de gas) y lo ubica en la línea de tiempo junto a una obra de la época.'}
]},
{id:'g7u3',title:'La oración clara',desc:'Oración simple, conectores y puntuación.',lessons:[
 {id:'g7u3l1',title:'Sujeto y predicado',time:50,std:'Produzco textos escritos que responden a necesidades específicas de comunicación, a procedimientos sistemáticos de elaboración y establezco nexos intertextuales y extratextuales.',dba:'DBA 8 (7°): produce textos atendiendo al público al que van dirigidos, al contexto de circulación y a los formatos de que dispone.',
  body:['La <b>oración</b> es la unidad mínima con sentido completo. Casi siempre tiene dos partes: el <b>sujeto</b>, de quién se habla, y el <b>predicado</b>, lo que se dice del sujeto.',
   'Para hallar el sujeto, pregúntale al verbo <b>¿quién?</b> o <b>¿quiénes?</b>. Su palabra más importante es el <b>núcleo</b>: un <b>sustantivo</b> o un <b>pronombre</b> (<i>familias, ella, nosotros</i>). Las demás (<i>las, bogotanas, de avena</i>) solo lo complementan.',
   'El predicado también tiene núcleo: el <b>verbo conjugado</b>. En "Las familias bogotanas recorren la ciclovía", el núcleo del predicado es <i>recorren</i>. Lo demás completa lo que se dice.',
   'El núcleo del sujeto y el verbo <b>concuerdan</b> en número y persona: <i>la familia recorre / las familias recorren</i>. El verbo concuerda con el núcleo, no con la palabra más cercana: "Los hinchas del equipo de Cali <i>celebran</i>", no "celebra".',
   'A veces el sujeto no está escrito, pero el verbo lo indica. En "Llegamos temprano" el sujeto es <i>nosotros</i>. Se llama <b>sujeto tácito</b>.',
   'El sujeto <b>no siempre va primero</b>. En "Por la Séptima bajan <i>los patinadores</i>" o "Cada domingo llegan <i>miles de familias</i>", aparece después del verbo. Pregunta ¿quiénes bajan? y lo encuentras.',
   'Con verbos como <i>encantar</i> o <i>gustar</i>, el sujeto es lo que gusta. En "A mi primo le encanta <i>la ciclovía</i>", ¿qué le encanta? La ciclovía. Si pasa a plural, el verbo cambia: "le encantan <i>las ciclovías</i>".'],
  bites:[
   {ej:'"Las familias bogotanas | recorren la ciclovía": primero el sujeto, luego el predicado.',check:{q:'En "Mi perro corre en el parque", ¿cuál es el sujeto?',o:['Mi perro','corre en el parque','el parque'],a:0,e:'¿Quién corre? Mi perro.'}},
   {ej:'"La vendedora de avena de la esquina madruga." ¿Quién madruga? La vendedora: ese es el núcleo.',ojo:'Las palabras con "de" (de avena, de la esquina) acompañan al núcleo, no son el núcleo.',check:{q:'En "Los niños del barrio juegan", ¿cuál es el núcleo del sujeto?',o:['niños','barrio','Los'],a:0,e:'¿Quiénes juegan? Los niños. "Del barrio" solo complementa.'}},
   {ej:'"Mi hermano menor maneja una bicicleta roja": el núcleo del predicado es maneja.',check:{q:'¿Qué palabra es el núcleo del predicado?',o:['El verbo conjugado','El primer sustantivo','La última palabra'],a:0,e:'El verbo conjugado es el corazón del predicado.'}},
   {ej:'"Los ciclistas que vienen de Suba llega tarde" está mal: el núcleo es ciclistas, así que debe decir llegan.',ojo:'No te dejes engañar por la palabra que está más cerca del verbo: busca el núcleo.',check:{q:'¿Cuál concuerda?',o:['Las vendedoras ofrecen jugo','Las vendedoras ofrece jugo'],a:0,e:'"Vendedoras" es plural: el verbo va en plural.'}},
   {ej:'"Compramos empanadas." ¿Quiénes? Nosotros, aunque no esté escrito.',check:{q:'En "Llegaste tarde", ¿cuál es el sujeto tácito?',o:['Tú','Yo','Ellos'],a:0,e:'"Llegaste" indica segunda persona: tú.'}},
   {ej:'"En la esquina toca una banda de rock": ¿quién toca? Una banda de rock.',ojo:'Aunque el sujeto vaya al final, el verbo sigue concordando con él: "llegan miles de familias".'},
   {ej:'"A mi hermana le gustan los patines": ¿qué le gusta? Los patines. Por eso "gustan", en plural.',ojo:'"Mi primo" no es el sujeto de "encantar": es a quien le encanta.',check:{q:'¿Cuál está bien?',o:['A mi primo le encantan las ciclovías','A mi primo le encanta las ciclovías'],a:0,e:'El sujeto es "las ciclovías", en plural; el verbo también va en plural.'}}],
  key:'Sujeto: de quién se habla (núcleo: sustantivo o pronombre). Predicado: qué se dice (núcleo: verbo). Concuerdan en número y persona.',
  co:'La ciclovía de Bogotá abre más de 120 kilómetros de vías cada domingo y festivo, de 7 de la mañana a 2 de la tarde.',
  act:{type:'build',prompt:'Arma cada oración tocando las piezas en orden.',rounds:[
   {q:'Une el sujeto con el predicado que concuerda.',pieces:['Las familias del barrio','recorren la ciclovía','recorre la ciclovía'],answers:[['Las familias del barrio','recorren la ciclovía']],slots:['Sujeto','Predicado'],hint:'"Familias" es plural: el verbo también debe ir en plural.'},
   {q:'Une el sujeto con el predicado que concuerda.',pieces:['El mecánico del parque','infla las llantas gratis','inflan las llantas gratis'],answers:[['El mecánico del parque','infla las llantas gratis']],slots:['Sujeto','Predicado'],hint:'"Mecánico" es singular.'},
   {q:'Ordena la oración empezando por el sujeto.',pieces:['Los','patinadores','bajan','por','la','Séptima'],answers:[['Los','patinadores','bajan','por','la','Séptima']],hint:'¿Quiénes bajan? Empieza por ellos.'},
   {q:'"La vendedora de jugos ofrece mango biche." Toca el núcleo del sujeto y luego el del predicado.',pieces:['La','vendedora','de','jugos','ofrece','mango','biche'],answers:[['vendedora','ofrece']],slots:['Núcleo del sujeto','Núcleo del predicado'],hint:'Pregúntale al verbo: ¿quién ofrece?'},
   {q:'"Mi hermano menor maneja una bicicleta roja." Toca el núcleo del sujeto y luego el del predicado.',pieces:['Mi','hermano','menor','maneja','una','bicicleta','roja'],answers:[['hermano','maneja']],slots:['Núcleo del sujeto','Núcleo del predicado'],hint:'El núcleo del predicado es el verbo conjugado.'}],
   e:'El sujeto responde a "¿quién?" y su núcleo concuerda con el verbo.'},
  quiz:[{q:'En "Los niños del barrio montan bicicleta", ¿cuál es el sujeto?',o:['Los niños del barrio','montan bicicleta','bicicleta','del barrio'],a:0,e:'¿Quiénes montan bicicleta? Los niños del barrio.',lv:'L'},
   {q:'¿Cuál es el núcleo del sujeto en "La vendedora de avena de la esquina madruga todos los domingos"?',o:['La','vendedora','avena','esquina'],a:1,e:'¿Quién madruga? La vendedora. "De avena" y "de la esquina" solo la complementan.',lv:'I'},
   {q:'Un compañero escribe: "Los ciclistas que vienen de Suba llega tarde". ¿Qué error tiene y por qué importa?',o:['Ninguno, está bien','Le falta una tilde','El verbo no concuerda con el núcleo "ciclistas": debe ser "llegan"; sin concordancia el lector duda de quién hace la acción','El sujeto debe ir al final'],a:2,e:'El verbo concuerda con el núcleo del sujeto, no con la palabra más cercana ("Suba").',lv:'C'}],
  tip:'Escriba sujetos en tarjetas azules y predicados en tarjetas naranjas; los estudiantes arman oraciones (serias y absurdas) y explican por qué concuerdan o no.'},
 {id:'g7u3l2',title:'Los conectores',time:50,std:'Reescribo un texto, teniendo en cuenta aspectos de coherencia (unidad temática, relaciones lógicas, consecutividad temporal) y cohesión (conectores, pronombres, manejo de modos verbales, puntuación).',dba:'DBA 8 (7°): produce textos atendiendo al público al que van dirigidos, al contexto de circulación y a los formatos de que dispone.',
  body:['Los <b>conectores</b> son palabras o expresiones que unen ideas y muestran qué relación hay entre ellas. Son el <b>puente</b> entre dos oraciones: sin ellos, un texto parece una lista de frases sueltas.',
   'Los conectores de <b>adición</b> suman ideas: <i>y, además, también, incluso</i>. Los de <b>contraste</b> oponen ideas o muestran un obstáculo: <i>pero, sin embargo, no obstante, aunque, en cambio, aun así</i>.',
   'Los conectores de <b>causa</b> explican el porqué: <i>porque, ya que, puesto que, debido a que</i>. Los de <b>consecuencia</b> muestran el resultado: <i>por eso, por lo tanto, así que, en consecuencia</i>.',
   'Otros, como <i>es decir</i>, no suman ni oponen: <b>explican</b> con otras palabras lo que se acaba de decir.',
   'Cambiar el conector cambia el sentido. "Llovió, <b>por eso</b> no fuimos al parque" no dice lo mismo que "Llovió, <b>pero</b> fuimos al parque" ni que "Llovió; <b>aun así</b>, fuimos al parque" (a pesar de eso).',
   '<i>Aunque</i> también puede abrir la oración: "Aunque llovió, fuimos al parque". Ojo con las comas: <i>sin embargo</i> y <i>por lo tanto</i> suelen ir entre comas.',
   'En una carta que pide algo, los conectores ordenan las razones y hacen más fuerte la petición: explican por qué se pide, qué pasa si no se hace y qué se ofrece a cambio.'],
  bites:[
   {ej:'Sin conector: "No hay parque. Los niños juegan en la calle." Con conector: "No hay parque; por eso, los niños juegan en la calle."',check:{q:'¿Para qué sirven los conectores?',o:['Para unir ideas y mostrar su relación','Para adornar el texto','Para alargar las oraciones'],a:0,e:'Son puentes: le dicen al lector cómo se relacionan las ideas.'}},
   {ej:'"Queremos un parque y también una biblioteca." "Quería ir a la ciclovía, pero se me pinchó la llanta."',ojo:'Adición suma (+); contraste pone un obstáculo o una diferencia.',check:{q:'¿Qué tipo de conector es "sin embargo"?',o:['Contraste','Adición','Causa'],a:0,e:'"Sin embargo" opone una idea a la anterior.'}},
   {ej:'"Uso casco, ya que protege la cabeza." "Me pinché la llanta, así que tuve que caminar."',ojo:'Truco: la causa va antes en el tiempo (el porqué); la consecuencia, después (el resultado).',check:{q:'"Estudiamos mucho; por lo tanto, aprobamos." ¿Qué muestra "por lo tanto"?',o:['Consecuencia','Causa','Contraste'],a:0,e:'Aprobar es el resultado de estudiar.'}},
   {ej:'"Sumapaz es un páramo, es decir, un ecosistema de montaña frío y húmedo."',check:{q:'¿Qué hace "es decir"?',o:['Explica con otras palabras','Suma una idea nueva','Opone dos ideas'],a:0,e:'"Es decir" aclara lo que se acaba de decir.'}},
   {ej:'"Estudié, pero perdí el examen" frente a "Estudié, por eso aprobé el examen": contraste en una, consecuencia en la otra.',check:{q:'"Hizo frío; aun así, salimos a pedalear." ¿Qué significa "aun así"?',o:['A pesar de eso','Por esa razón','Es decir'],a:0,e:'Salimos a pesar del frío: es contraste.'}},
   {ej:'"Aunque sabemos que no es fácil, confiamos en su compromiso." "El presupuesto es limitado; sin embargo, un parque pequeño es posible."',ojo:'Escribe "sin embargo" entre comas o después de punto y coma: "…; sin embargo, …".'},
   {ej:'En una carta al alcalde local de Kennedy: "Los niños juegan en la calle porque no hay parque, así que corren peligro".',check:{q:'En una carta de petición, ¿qué hacen los conectores?',o:['Ordenan las razones y fortalecen la petición','Hacen la carta más corta','Reemplazan la firma'],a:0,e:'Unen cada razón con la petición y la hacen más convincente.'}}],
  key:'Adición: y, además. Contraste: pero, sin embargo. Causa: porque, ya que. Consecuencia: por eso, por lo tanto.',
  co:'Cualquier persona puede presentar un derecho de petición ante su alcaldía local; por regla general, la entidad debe responder en quince días hábiles.',
  act:{type:'comic',prompt:'Sara y Tomás preparan una carta al alcalde local. Completa cada globo con el conector correcto.',panels:[
   {who:'Sara',face:'🙋‍♀️',say:'Queremos pedir un parque en el lote vacío {{porque|pero|además}} los niños no tienen dónde jugar.'},
   {who:'Tomás',face:'😟',say:'Hoy juegan en la calle, {{así que|en cambio|es decir}} corren peligro con los carros.'},
   {who:'Sara',face:'🤔',say:'El lote está lleno de basura; {{además|sin embargo|en cambio}}, de noche allí se reúnen personas que asustan a los vecinos.'},
   {who:'Tomás',face:'🧐',say:'El presupuesto es limitado; {{sin embargo|por eso|además}}, un parque pequeño cuesta menos que atender accidentes.'},
   {who:'Sara',face:'😃',say:'Un parque sería un lugar seguro, {{es decir|aunque|por lo tanto}}, un espacio para jugar sin miedo.'},
   {who:'Tomás',face:'✍️',say:'{{Aunque|Por lo tanto|Además}} no es fácil, confiamos en el alcalde. ¡Firmemos!'}],
   e:'Causa (porque), consecuencia (así que), adición (además), contraste (sin embargo, aunque) y explicación (es decir): cada conector ordena una razón de la carta.'},
  quiz:[{q:'¿Qué tipo de conector es "sin embargo"?',o:['Adición','Contraste','Causa','Consecuencia'],a:1,e:'"Sin embargo" opone una idea a la anterior.',lv:'L'},
   {q:'"No había parque en el barrio; ___, los niños jugaban en la calle." ¿Qué conector completa mejor la oración?',o:['por eso','aunque','sin embargo','es decir'],a:0,e:'Jugar en la calle es la consecuencia de no tener parque.',lv:'I'},
   {q:'Compara "Estudié, pero perdí el examen" con "Estudié, por eso aprobé el examen". ¿Qué muestra el cambio de conector?',o:['Que los conectores son decorativos','Que el conector cambia la relación entre las ideas: contraste en una, consecuencia en la otra','Que las dos oraciones dicen lo mismo','Que es mejor no usar conectores'],a:1,e:'El conector le dice al lector cómo relacionar las ideas; cambiarlo cambia el sentido.',lv:'C'}],
  tip:'Entregue una carta sin conectores y pida leerla en voz alta; luego los grupos la reescriben usando al menos un conector de cada tipo.'},
 {id:'g7u3l3',title:'La coma y el punto',time:50,std:'Produzco textos orales, en situaciones comunicativas que permiten evidenciar el uso significativo de la entonación y la pertinencia articulatoria.',dba:'DBA 5 (7°): comprende el sentido global de los textos que lee, la intención de quien los produce y el contexto en que se producen.',
  body:['Cuando hablamos, hacemos <b>pausas</b> y cambiamos el <b>tono</b>. Al escribir, esas pausas se marcan con <b>signos de puntuación</b>. Una coma puede cambiarlo todo: "Vamos a comer, niños" invita a los niños a la mesa; "Vamos a comer niños" dice algo muy distinto.',
   'La <b>coma</b> marca una pausa breve. Separa los elementos de una <b>enumeración</b>: <i>papa, yuca y plátano</i>. Antes de la <i>y</i> final no va coma.',
   'La coma aísla el <b>vocativo</b>, es decir, el nombre de aquel a quien se le habla: <i>Laura, ven</i>. También va después de <i>sí</i> o <i>no</i> cuando responden: "No, gracias".',
   'La coma encierra una <b>explicación</b> en medio de la oración: <i>Bogotá, la capital, tiene…</i>. La explicación va entre dos comas, una antes y otra después.',
   'La coma <b>nunca</b> se pone entre el sujeto y el verbo: "Mi hermana estudia", no "Mi hermana, estudia".',
   'El <b>punto</b> marca una pausa larga y cierra una oración con sentido completo. Dos oraciones completas no se pegan con coma: "Llegamos tarde. El bus se varó".',
   'El <b>punto y seguido</b> separa oraciones del mismo párrafo; el <b>punto y aparte</b> cierra un párrafo, y el <b>punto final</b>, el texto. Leer en voz alta respetando los signos ayuda a comprobar la puntuación.'],
  bites:[
   {ej:'"No quiero ir contigo" rechaza el plan; "No, quiero ir contigo" dice que sí quieres ir.',check:{q:'¿Qué marcan los signos de puntuación al escribir?',o:['Las pausas y el tono al hablar','Las tildes','El número de páginas'],a:0,e:'Los signos llevan a lo escrito las pausas de la voz.'}},
   {ej:'"Traigan cuaderno, lápiz, borrador y regla."',ojo:'Error típico: "cuaderno, lápiz, y regla". Antes de la "y" final no va coma.',check:{q:'¿Cuál está bien?',o:['Compré papa, yuca y plátano.','Compré papa, yuca, y plátano.'],a:0,e:'En una enumeración simple no va coma antes de la "y".'}},
   {ej:'La mamá le dice a Laura: "Laura, cierra la puerta, por favor".',check:{q:'En "Niños, a la mesa", ¿qué es "niños"?',o:['Un vocativo','Una enumeración','El verbo'],a:0,e:'Es a quien se le habla: vocativo, separado con coma.'}},
   {ej:'"Gabriel García Márquez, autor de Cien años de soledad, nació en Aracataca."',ojo:'Si quitas lo que va entre comas, la oración sigue teniendo sentido: "Gabriel García Márquez nació en Aracataca".'},
   {ej:'"Los hinchas de Millonarios llenaron el estadio", sin coma después de Millonarios.',check:{q:'¿Cuál está bien puntuada?',o:['Mi mamá trabaja en Bucaramanga.','Mi mamá, trabaja en Bucaramanga.'],a:0,e:'No se separa el sujeto del verbo con coma.'}},
   {ej:'"Llegamos al estadio a las tres. La fila ya daba la vuelta a la cuadra."',ojo:'Si lo que va antes y después de la coma son oraciones completas, usa punto.',check:{q:'¿Cuál está bien?',o:['Hoy hace sol. Mañana lloverá.','Hoy hace sol, mañana lloverá.'],a:0,e:'Son dos oraciones completas: se separan con punto.'}},
   {ej:'Este texto tiene punto y seguido entre oraciones, punto y aparte al cambiar de párrafo y punto final al terminar.',check:{q:'¿Qué punto cierra un párrafo?',o:['Punto y aparte','Punto y seguido','Punto final'],a:0,e:'Después del punto y aparte empieza un párrafo nuevo.'}}],
  key:'Coma: pausa breve (enumeración, vocativo, explicación). Punto: pausa larga que cierra una idea completa.',
  co:'"Vamos a comer, niños" frente a "Vamos a comer niños": la coma del vocativo salva a los niños.',
  act:{type:'fix',prompt:'La nota de Camila tiene errores de puntuación. Toca cada error y elige el arreglo.',text:'La abuela gritó desde la cocina: "Vamos a {{comer, niños|comer niños}}". En la mesa había {{papa, yuca y plátano|papa, yuca, y plátano|papa yuca y plátano}}. {{Laura, pásame|Laura pásame}} el ají, por favor. {{Mi primo, el menor,|Mi primo el menor,|Mi primo, el menor}} no quiso sopa. {{Los tíos llegaron|Los tíos, llegaron}} tarde. {{El bus se varó. Tuvieron|El bus se varó, tuvieron}} que caminar. ¿Más jugo? {{No, gracias|No gracias}}.',e:'La coma separa enumeraciones, aísla el vocativo y encierra explicaciones, pero nunca separa el sujeto del verbo. Dos oraciones completas se separan con punto.'},
  quiz:[{q:'¿Qué signo cierra una oración con sentido completo?',o:['La coma','El punto','Las comillas','El guion'],a:1,e:'El punto marca la pausa larga que cierra una oración.',lv:'L'},
   {q:'¿Cuál oración está bien puntuada?',o:['Mi hermana, estudia en Medellín.','Mi, hermana estudia en Medellín.','Mi hermana estudia, en Medellín.','Mi hermana estudia en Medellín.'],a:3,e:'No va coma entre el sujeto ("Mi hermana") y el verbo, ni entre el verbo y su complemento.',lv:'I'},
   {q:'Compara "No quiero ir contigo" con "No, quiero ir contigo". ¿Qué muestra este ejemplo?',o:['Que la coma es decorativa','Que las dos significan lo mismo','Que la coma solo se usa en poemas','Que la puntuación puede invertir el sentido de lo que se dice'],a:3,e:'En la primera, la persona rechaza ir; en la segunda, responde "no" a otra cosa y afirma que sí quiere ir.',lv:'C'}],
  tip:'Lea en voz alta un mismo párrafo con pausas distintas y pida a los estudiantes puntuarlo según lo que oyen; luego comparen las versiones y cómo cambia el sentido.'}
]}
]};
export default grade;
